CustomField.formula:
IF(
    OR(
        ISBLANK(TDC_EC__Files_Ids__c),
        LEFT(TDC_EC__Files_Ids__c, 3) = '069'
    ),
    HYPERLINK(
        '/sfc/servlet.shepherd/document/download/' + LEFT(TDC_EC__Files_Ids__c, 18) + '?operationContext=S',
        IMAGE(
            '/resource/tdc_ec__Lightning_Resource/icons/doctype/' + RIGHT(LEFT(TDC_EC__Files_Ids__c, 31), 12),
            ''
        )
    ),
    HYPERLINK(
        '/servlet/servlet.FileDownload?file=' + LEFT(TDC_EC__Files_Ids__c, 18),
        IMAGE(
            '/resource/tdc_ec__Lightning_Resource/icons/doctype/' + RIGHT(LEFT(TDC_EC__Files_Ids__c, 31), 12),
            ''
        )
    )
) & " "
